// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // General rule: After construction and initialization via initializer path, owner() returns the actual owner address (the deployer/pranked initializer caller).
    // The mutant that hardcodes owner() to return address(0) will break this for some initializer caller addresses provided by the fuzzer.
    function testFuzz_property(address initialOwner) public {
        // restrict to non-zero to keep meaningful owner (but allow zero too to not exclude bug triggers)
        // We keep domain wide; allow any address including zero.

        // Call initialize as if initialOwner is the caller: initializer sets owner to _msgSender() during __Ownable_init
        vm.prank(initialOwner);
        // initialize expects IERC20 etc. We can pass zero addresses for these because initializer only sets owner, keeper and some fields
        // Provide plausible nonzero addresses for external contracts to avoid potential require/use; but initializer doesn't interact with them beyond assignments.
        address zeroAddr = address(0);
        c.initialize(
            IERC20(zeroAddr),
            IERC20(zeroAddr),
            IRewardRouterV2(zeroAddr),
            IGlpManager(zeroAddr),
            address(0),
            address(0)
        );

        // Now read owner via public getter. This should equal initialOwner in the reference implementation.
        address reportedOwner = c.owner();

        // Single assertion: in the correct contract this holds for all initialOwner; the mutant returning address(0) will fail for any initialOwner != address(0).
        assertTrue(reportedOwner == initialOwner);
    }
}

