pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the initial owner address (must be non-zero to be meaningful)
    function testFuzz_property(address initialOwner) public {
        // keep domain wide but ignore zero address which Ownable initializer would not set as a useful owner
        vm.assume(initialOwner != address(0));

        // Call initialize so Ownable initializer sets owner to msg.sender in __Ownable_init via _transferOwnership
        // __Ownable_init uses _msgSender() (which is the caller). We want owner to be initialOwner, so we prank.
        vm.prank(initialOwner);
        c.initialize(
            IERC20(address(0)),
            IERC20(address(0)),
            IRewardRouterV2(address(0)),
            IGlpManager(address(0)),
            address(0),
            address(0)
        );

        // Read owner via public getter; the correct contract returns initialOwner, mutant returns address(0) for all.
        address returnedOwner = c.owner();

        // General rule: after initialize called by initialOwner, owner() must equal initialOwner.
        assertTrue(returnedOwner == initialOwner);
    }
}

// Note: import types used above must match C's initialize signature; declare minimal interfaces to satisfy compiler
interface IERC20 {
    function transferFrom(address, address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
}
interface IRewardRouterV2 {
    function mintAndStakeGlp(address, uint256, uint256, uint256) external returns (uint256);
}
interface IGlpManager { function vault() external view returns (address); }

