    C c;

    function setUp() public { c = new C(); }

    // fuzz the initializer address to ensure owner() returns the initializer (the reference) and
    // the mutant that returns address(0) will fail for any non-zero initializer
    function testFuzz_property(address initializer) public {
        // keep initializer as a valid EOA-like address (non-zero)
        vm.assume(initializer != address(0));

        // The initialize function in C is external and uses initializer modifier; the call should be
        // made by the intended initializer. Use vm.prank to simulate caller.
        vm.prank(initializer);
        // supply minimal valid args: pass zero addresses for tokens/managers, keeper as initializer
