            // address _dnGmxJuniorVault
            address(0),
            // address _keeper
            initializer
        );

        // Query owner via public function. The reference contract returns the initializer; the mutant returns address(0).
        address reportedOwner = c.owner();

        // Single assertion: for all initializer != address(0), the contract's owner() must equal initializer.
        assertTrue(reportedOwner == initializer);
