pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz the initializer address so the fuzzer can find a case where owner() differs
    function testFuzz_property(address initializer) public {
        // keep initializer in the wide admissible domain but not zero (initializer should be a real EOA)
        vm.assume(initializer != address(0));

        // Call initialize as the fuzzed initializer
        vm.prank(initializer);
        c.initialize(
            IERC20(address(0)),
            IERC20(address(0)),
            IRewardRouterV2(address(0)),
            IGlpManager(address(0)),
            address(0),
            initializer
        );

        // Query owner via try/catch to capture potential revert (owner() is view and should not revert)
        bool ok;
        address ret;
        try c.owner() returns (address v) {
            ok = true;
            ret = v;
        } catch {
            ok = false;
            ret = address(0);
        }

        // General rule: after initialize called by `initializer`, the contract's owner() returns that initializer address.
        // The mutant implementation returns address(0) always, so for some fuzzed `initializer` the above will fail.
        assertTrue(ok && ret == initializer);
    }
}

