pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initializer) public {
        // keep domain wide but avoid zero address which is a valid but uninteresting initializer
        vm.assume(initializer != address(0));

        // Call initialize as the fuzzed initializer
        vm.prank(initializer);
        // we must supply the parameters: _sGlp, _usdc, _rewardRouter, _glpManager, _dnGmxJuniorVault, _keeper
        // use harmless zero-address/mocks for external contracts where allowed; C will call glpManager.vault() in init
        // so provide a minimal GlpManager mock that returns a non-zero vault address
        SimpleGlpManager glpManager = new SimpleGlpManager(address(0xBA5E));
        // other external contract interfaces can be zero addresses because initialize only stores them
        c.initialize(
            IERC20(address(0)),
            IERC20(address(0)),
            IRewardRouterV2(address(0)),
            IGlpManager(address(glpManager)),
            address(0xBEEF),
            initializer
        );

        // The general rule: after initialize called by `initializer`, owner() should return initializer.
        // The mutant returns address(0) for some initializer, so this assert will fail on the mutant for those inputs.
        assertTrue(c.owner() == initializer);
    }
}

// Minimal helper to satisfy glpManager.vault() call during initialize
contract SimpleGlpManager is IGlpManager {
    address private _vault;
    constructor(address vault_) { _vault = vault_; }
    function vault() external view returns (address) { return _vault; }
}

// Interfaces needed by the test (kept minimal to match imports used above)
interface IERC20 {
    function approve(address, uint256) external returns (bool);
}
interface IGlpManager {
    function vault() external view returns (address);
}
interface IRewardRouterV2 {}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // General rule: for any caller address 'actor', calling c.owner() as that actor must return the stored owner address (the deployer/contract owner), not the caller.
    // We fuzz an arbitrary actor address. We ensure actor is not the zero address and not the deployer (this keeps the domain wide).
    function testFuzz_property(address actor) public {
        // keep actor wide but avoid trivial equality to address(0) and the test contract (which deployed c)
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Call owner() from the fuzzed actor using prank to simulate external caller
        bool ok;
        address reportedOwner;
        vm.prank(actor);
        try c.owner() returns (address o) {
            ok = true;
            reportedOwner = o;
        } catch {
            ok = false;
            reportedOwner = address(0);
        }

        // The reference contract always returns the stored owner (the test contract/address that initialized c via setUp),
        // which equals address(this) because setUp deployed c. Thus when actor != address(this), owner() must NOT equal actor.
        // We assert that either the call reverted (ok == false) OR the returned owner is not equal to the caller (reportedOwner != actor).
        // For the correct contract, the call completes and reportedOwner == address(this) != actor, so the assertion holds for all actors.
        // The mutant that returns msg.sender will make reportedOwner == actor for some actor, causing this assertion to fail.
        assertTrue(ok == false || reportedOwner != actor);
    }
}

