pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // General rule: For any caller (msg.sender) the stored owner() (set during initialization) equals the value returned by owner() when called directly by that caller; the mutant returning tx.origin will differ when the call is proxied through an intermediate caller. We fuzz the intermediate caller address.
    function testFuzz_property(address proxy) public {
        // keep proxy non-zero to be meaningful
        vm.assume(proxy != address(0));
        // initialize contract as deployer (setUp deploys c with this test contract as sender in new C()).
        // Need to run initializer to set owner to this test contract address
        // The initializer modifier in C requires either being non-contract or correct sequence; our test contract is a contract, so we must call initialize via a non-contract EOA address.
        // Use an EOA fuzzed address to call initialize via vm.prank.
        address eoa = address(0xBEEF);
        vm.deal(eoa, 1);
        vm.prank(eoa);
        // Call initialize with some dummy parameters (we can pass zero addresses for interfaces since functions used in initialize only store them)
        c.initialize(
            IERC20(address(0)),
            IERC20(address(0)),
            IRewardRouterV2(address(0)),
            IGlpManager(address(0)),
            address(0x1),
            address(0x2)
        );

        // Now owner should be the EOA that called initialize (eoa)
        // We will call c.owner() directly from two different callers and also via a proxy contract to detect tx.origin vs _owner behavior.

        // Direct call as EOA: simulate direct call by prank as eoa
        vm.prank(eoa);
        address ownerDirect = c.owner();

        // Deploy a small proxy that will call c.owner() (external call). The proxy's call will have msg.sender = proxyContract, tx.origin = the EOA we instruct via vm.prank.
        ProxyCaller p = new ProxyCaller();

        // Case A: call proxy with tx.origin == eoa and msg.sender == proxyCaller
        vm.prank(eoa, eoa);
        address ownerViaProxy = p.callOwner(address(c));

        // The correct contract returns the same stored owner regardless of whether call comes directly or via proxy (ownerDirect == ownerViaProxy)
        // The mutant that returns tx.origin would return eoa when called directly by eoa, but when called via proxy would still see tx.origin == eoa as well — to force difference we must make tx.origin differ from stored owner by causing initialize owner to be different from tx.origin used in proxied call.
        // To create a diverging tx.origin, we set stored owner to one EOA and then call via another EOA through the proxy. We'll set up another EOA2.

        address eoa2 = address(uint160(uint256(keccak256(abi.encodePacked(proxy, block.timestamp)))));
        vm.deal(eoa2, 1);

        // Re-initialize a fresh instance where owner is eoa (already done). Now call via proxy with tx.origin = eoa2 and msg.sender = proxy contract.
        vm.prank(eoa2, eoa2);
        address ownerViaProxyFromEoa2 = p.callOwner(address(c));

        // The universal property we assert: the stored owner observed directly by the owner() call when made by the stored owner EOA equals the owner observed when calling via any proxy with a different tx.origin only for the correct contract; the mutant will differ for some proxy-origin combination.
        // We assert that ownerDirect == ownerViaProxyFromEoa2. This must hold for the correct contract for all proxy addresses and EOAs; the mutant (which returns tx.origin) will fail when tx.origin != stored owner.
        assertTrue(ownerDirect == ownerViaProxyFromEoa2);
    }
}

contract ProxyCaller {
    function callOwner(address target) external returns (address) {
        (bool ok, bytes memory ret) = target.call(abi.encodeWithSignature("owner()"));
        require(ok);
        return abi.decode(ret, (address));
    }
}

