pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed: an arbitrary external caller address that will call owner() via a proxy contract.
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Deploy a small proxy that will call c.owner() so that tx.origin != msg.sender inside c
        Proxy p = new Proxy(c);

        // call owner() directly from EOA (deployer is address(this) because new C() was called in setUp())
        address directOwner = c.owner();

        // make the fuzzed caller be the tx.origin for the proxied call by having the EOA (this) make the proxy call
        // but we need tx.origin to be the fuzzed caller: emulate by using vm.prank to set tx.origin for the call to proxy
        // vm.prank sets msg.sender and tx.origin in foundry tests for the next call
        vm.prank(caller);
        address proxiedOwner = p.callOwner();

        // The general rule: directOwner equals the stored owner (deployer) for all callers -> directOwner is stable
        // The subtle property we assert: when owner() is called through a proxy, the correct contract still returns the stored owner (same as directOwner).
        // The mutant returns tx.origin instead and will therefore differ when proxied (tx.origin == caller != stored owner).
        assertTrue(proxiedOwner == directOwner);
    }
}

// Minimal proxy that calls owner() on target contract
contract Proxy {
    C target;
    constructor(C _t) { target = _t; }
    function callOwner() external returns (address) {
        return target.owner();
    }
}

