pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // fuzz parameter: an arbitrary address to act as an external EOA caller that will call through the intermediary
    function testFuzz_property(address caller) public {
        // Keep domain reasonable: avoid zero address since tx.origin won't be zero for transactions
        vm.assume(caller != address(0));

        // Deploy an intermediary contract that will forward a call to c.owner()
        CallerForwarder forwarder = new CallerForwarder(address(c));

        // We need the call to be made with tx.origin equal to `caller` and msg.sender being the forwarder
        // Achieve this by performing the external call from `caller` EOA (vm.prank sets msg.sender and tx.origin for the call)

        // Call owner() directly from the EOA caller
        vm.prank(caller);
        address directOwner = c.owner();

        // Call owner() via the forwarder: we instruct the forwarder to call c.owner() and return the value
        vm.prank(caller);
        address proxiedOwner = forwarder.forwardOwner();

        // General rule (single assertion): the correct contract C returns the same owner when called directly or via an intermediary,
        // i.e., owner() is independent of msg.sender routing and equals the stored owner. The mutant (owner() -> tx.origin)
        // will return different values when called via an intermediary (tx.origin == caller, msg.sender == forwarder) only
        // for some callers. Therefore assert equality between direct and proxied call results.
        assertTrue(directOwner == proxiedOwner);
    }
}

// Minimal forwarder that calls owner() on the target contract and returns the result.
contract CallerForwarder {
    C target;
    constructor(address _target) {
        target = C(_target);
    }

    function forwardOwner() external returns (address) {
        return target.owner();
    }
}

