pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // General rule: calling owner() through an intermediate contract must return the stored owner (deployer)
    // For the mutant that returns tx.origin, calling via an intermediate contract will return the EOA caller
    // instead of the stored owner, so the property will fail for some fuzzed caller addresses.
    function testFuzz_property(address caller) public {
        // keep caller in EOA-like address space (non-zero)
        vm.assume(caller != address(0));

        // Deploy an intermediary contract that will call c.owner() and return the value it sees
        CallerProxy proxy = new CallerProxy(address(c));

        // Ensure caller has some ETH to be tx.origin when calling via proxy
        vm.deal(caller, 1 ether);

        // Have the fuzzed EOA call the proxy which in turn calls c.owner()
        vm.prank(caller);
        address returnedByProxy = proxy.callOwner();

        // The correct contract stores its owner as the deployer (address(this) of setUp deployer)
        // When we deployed c in setUp(), tx.origin was the test runner; Foundry deploys contracts from address(this)
        // which is the test contract. So the stored owner is the test contract address. Read direct owner()
        address directOwner = c.owner();

        // The universal property we assert: when viewed through an intermediate contract, owner() must equal the stored owner.
        // If the contract uses tx.origin instead of the stored owner, returnedByProxy will equal the EOA caller (tx.origin)
        // and may differ from directOwner, causing the assertion to fail on the mutant for some caller values.
        assertTrue(returnedByProxy == directOwner);
    }
}

// Minimal intermediary that calls C.owner() and returns its result
contract CallerProxy {
    C c;
    constructor(address _c) {
        c = C(_c);
    }
    function callOwner() external returns (address) {
        return c.owner();
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // The fuzzer will supply an arbitrary EOA caller address that will act as tx.origin
    // and arbitrary intermediateSalt to vary the deployed proxy address deterministically.
    function testFuzz_property(address originActor, uint256 intermediateSalt) public {
        // keep domain wide but avoid the zero address for origin since tx.origin cannot be zero in practice
        vm.assume(originActor != address(0));

        // Deploy a simple forwarder/proxy contract from the originActor EOA context so that
        // when the forwarder calls c.owner(), tx.origin == originActor and msg.sender == forwarder.
        // We deploy the Forwarder via CREATE using originActor as the deployer by using vm.prank.

        vm.startPrank(originActor);
        Forwarder f = new Forwarder();
        vm.stopPrank();

        // Now call owner() directly from the origin EOA and record whether the call succeeds and the returned value.
        bool okDirect;
        address returnedDirect;
        try c.owner() returns (address a) {
            okDirect = true;
            returnedDirect = a;
        } catch {
            okDirect = false;
            returnedDirect = address(0);
        }

        // Now have the forwarder call owner() on behalf of the same tx.origin (originActor)
        // The forwarder will perform a call to c.owner() (so tx.origin == originActor, msg.sender == address(f)).
        bool okForwarded;
        address returnedForwarded;
        try f.callOwner(c) returns (address a) {
            okForwarded = true;
            returnedForwarded = a;
        } catch {
            okForwarded = false;
            returnedForwarded = address(0);
        }

        // General rule (single assertion): For the correct contract, calling owner() directly from the origin EOA
        // and calling it via a deployed forwarder whose tx.origin is the same originEOA must both succeed and return the same stored owner address.
        // The mutant (owner() => tx.origin) will return tx.origin when called via the forwarder (which equals originActor),
        // but when called directly may return the stored owner (the deployer of C). Therefore the property distinguishes them.

        // We assert the conjunction: both calls succeeded AND returned values are equal.
        assertTrue(okDirect && okForwarded && (returnedDirect == returnedForwarded));
    }
}

// Minimal forwarder that simply calls owner() on target and returns the address result (or bubbles revert)
contract Forwarder {
    function callOwner(C target) external returns (address) {
        // Here we call the public owner() and return its result.
        return target.owner();
    }
}

