pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter is an address candidate to compare owner() against.
    // General rule: owner() should return the contract's stored owner (the one set on initialization via Ownable)
    // The mutant returns address(this) instead, so for most fuzzed addresses addr != address(c)
    // calling owner() and comparing to address(c) will detect the mutant.
    function testFuzz_property(address addr) public {
        // Keep domain wide but avoid the rare case where the fuzzed addr equals the contract address
        // (we still allow it; if addr == address(c) the property remains meaningful).

        // Read owner() from the contract. This is the single observation used in the assertion.
        address reportedOwner = c.owner();

        // The correct contract's owner should be the deployer (this test contract), not address(c).
        // We assert that reportedOwner is not equal to address(c) OR equals the expected deployer.
        // Here we assert the universal property that owner() != address(c) || owner() == address(this).
        // For the reference contract owner() == address(this) is false; actual owner is this test contract set in initializer,
        // so reportedOwner == address(this) must hold for reference; the mutant returns address(c) causing the assertion to fail for some inputs.

        // Exactly one assertTrue as required. It encodes that owner() must equal the externally set owner (this test contract) and thus must not be address(c).
        assertTrue(reportedOwner == address(this), "owner() must report the externally set owner (the deployer)");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // fuzz the caller address to ensure deployer (owner) can be varied; the property is:
    // After construction the stored owner != address(c) (the contract) for normal deploys, so owner() should not equal address(c).
    // The mutant that returns address(this) will make owner() == address(c) and thus violate the assertion for some inputs.
    function testFuzz_property(address fuzz) public {
        // admissible domain: fuzz != address(0) to avoid degenerate address, but keep wide
        vm.assume(fuzz != address(0));

        // The reference contract's initializer sets the owner to the deployer (which is this test contract when calling initialize).
        // However C uses Initializable and the Ownable initializer sets owner to _msgSender() during __Ownable_init call inside initialize.
        // The contract was constructed via new C() in setUp(), so its _owner is zero until initialize is called. We exercise owner() directly
        // to observe its current value after construction (the storage _owner is private and initially zero). For the reference, owner() returns that stored owner (likely address(0)).

        // We assert the general property: owner() != address(c) OR owner() == address(c) ? We need a universal property that reference satisfies always.
        // The safe universal property: owner() != address(c) || owner() == address(0)
        // But mutant returns address(c) always, which may equal address(0) false. We want a property that reference always satisfies and mutant violates for some input.

        // Instead, call owner() and check that it's equal to the internal stored owner (we can only observe via owner()). Both contracts expose owner() only.
        // The distinguishing fact from the change: reference owner() == _owner (some address possibly != address(c)), mutant owner() == address(c).
        // We can assert that owner() is not equal to address(c) OR owner() == address(0). This holds for reference in all runs (since stored _owner cannot be address(c) immediately after construction),
        // but the mutant will return address(c) making the assertion fail when stored _owner != address(c) and != address(0). To ensure the reference satisfies for ALL fuzz inputs, we restrict fuzz to addresses not equal to address(c) and not zero,
        // then we call initialize via a prank from a different deployer (fuzz) so the stored owner becomes fuzz (not address(c)). The reference will report owner() == fuzz, which is != address(c). The mutant will return address(c) and differ.

        // Make fuzz be the initializer owner by calling initialize as fuzz.
        // Prepare dummy args for initialize: pass zero addresses for interfaces where unused for this test (allowed by vm.assume not to be zero?) Keep them non-zero where required.
        address dummyAddr = address(1);
        vm.prank(fuzz);
        // call initialize with minimal non-zero addresses so initializer succeeds
        c.initialize(IERC20(dummyAddr), IERC20(dummyAddr), IRewardRouterV2(dummyAddr), IGlpManager(dummyAddr), dummyAddr, fuzz);

        // Now after initialize the stored owner should be 'fuzz' in reference, and owner() should return fuzz. Also fuzz != address(c) by assumption (ensure that):
        vm.assume(fuzz != address(c));

        address reportedOwner = c.owner();

        // Single assertion: in the correct contract, after initialize by 'fuzz', owner() equals the initializer address 'fuzz' (the stored owner) and therefore is not address(c).
        // The mutant that returns address(this) will make reportedOwner == address(c) and thus this assertion will fail for that mutant for those fuzz values.
        assertTrue(reportedOwner == fuzz && reportedOwner != address(c));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the deployer-like actor address; for the correctly-initialized OwnableUpgradeable,
    // owner() should return the stored owner (the deployer msg.sender during initialization),
    // which in our test is address(this) because setUp deployed c. To distinguish mutant behavior
    // we instead check that owner() equals the recorded owner returned by the contract and that
    // for any arbitrary address 'actor' (fuzzed) if actor != address(c) then owner() != actor —
    // but we must expose a general rule that the reference satisfies for ALL inputs and the
    // mutant breaks for SOME. We pick as fuzzed input an address attacker and assert that
    // owner() != address(c) OR owner() == address(this) depending on deployment; more directly,
    // the universal property used here: owner() != address(c) holds for the reference when the
    // stored owner is not the contract. We let the fuzzer supply an address 'maybeOwner' and
    // check that the contract's owner() equals the stored owner and not address(c) when the
    // stored owner differs. Because setUp deploys c from this test contract, in the reference
    // owner() should equal address(this) and still equal address(c) only in the mutant. To ensure
    // the test can fail on the mutant for some fuzzed input, we assert that owner() == address(this) || owner() != address(c).
    // To satisfy the strict requirements (single assert reading c), we assert that owner() == address(this) || owner() != address(c).

    function testFuzz_property(address maybeAddr) public {
        // Keep domain wide; no assumptions
        // read the owner via the public getter
        address reportedOwner = c.owner();

        // The general rule we assert (single assertion):
        // For all inputs, the correct contract never reports the contract address as owner unless it was set that way during init.
        // In our setup the stored owner is the test contract (deployer of c), so the reference will report address(this) and NOT address(c).
        // The mutant that returns address(this) for owner() will instead report address(c) causing divergence for some environments.

        // Single observation assertion reading c's public surface (owner())
        // This is true for the reference in our setup: reportedOwner == address(this) (deployer) AND reportedOwner != address(c).
        // The mutant will make reportedOwner == address(c) which will cause the assertion to fail for some fuzz inputs (the fuzzer explores maybeAddr but we keep one assert on c).
        assertTrue(reportedOwner == address(this) && reportedOwner != address(c));
    }
}

